#include <string.h>
#include <unistd.h>

// Assuming RSFilter and rsfilter_to_dot are defined in the codebase
// and rsfilter_to_dot returns a dynamically allocated string representing the DOT content.

void visualize_filter_graph(RSFilter *filter) {
    if (!filter) {
        fprintf(stderr, "Warning: Invalid filter provided.\n");
        return;
    }

    char *dot_content = rsfilter_to_dot(filter);
    if (!dot_content) {
        fprintf(stderr, "Warning: Failed to generate DOT content.\n");
        return;
    }

    FILE *dot_file = fopen("/tmp/filter_graph.dot", "w");
    if (!dot_file) {
        perror("Failed to open temporary DOT file");
        free(dot_content);
        return;
    }

    fprintf(dot_file, "%s", dot_content);
    fclose(dot_file);
    free(dot_content);

    char png_path[] = "/tmp/filter_graph.png";
    char command[256];

    snprintf(command, sizeof(command), "dot -Tpng /tmp/filter_graph.dot -o %s", png_path);
    int dot_result = system(command);

    if (dot_result != 0) {
        fprintf(stderr, "Warning: Failed to generate PNG image from DOT.\n");
        return;
    }

    snprintf(command, sizeof(command), "gnome-open %s", png_path);
    int open_result = system(command);

    if (open_result != 0) {
        fprintf(stderr, "Warning: Failed to open PNG image with gnome-open.\n");
    }
}

#include <stdlib.h>
