// Assume RSFilter is defined elsewhere
typedef struct RSFilter RSFilter;

// Assume build_dot_representation is a helper function defined elsewhere
char* build_dot_representation(RSFilter *filter);

void visualize_filter_graph(RSFilter *filter) {
    if (!filter) {
        return;
    }

    char *dot_content = build_dot_representation(filter);
    if (!dot_content) {
        return;
    }

    FILE *temp_file = tmpfile();
    if (!temp_file) {
        free(dot_content);
        return;
    }

    fprintf(temp_file, "%s", dot_content);
    free(dot_content);

    rewind(temp_file);

    char *dot_output_path = "/tmp/filter_graph.png";

    char command[512];
    snprintf(command, sizeof(command), "dot -Tpng -o %s", dot_output_path);

    FILE *dot_process = popen(command, "w");
