// Assume RSFilter is defined in the codebase; using a placeholder here
typedef struct RSFilter {
    int valid;
} RSFilter;

// Placeholder for the helper function to generate DOT representation
char* generate_dot_representation(RSFilter *filter) {
    // Dummy implementation for illustration
    char *dot = malloc(100 * sizeof(char));
    snprintf(dot, 100, "digraph G { a -> b }");
    return dot;
}

void visualize_filter_graph(RSFilter *filter) {
    if (!filter || !filter->valid) {
        return;
    }

    char *dot_content = generate_dot_representation(filter);
    if (!dot_content) {
        return;
    }

    FILE *dot_file = tmpfile();
    if (!dot_file) {
        free(dot_content);
        return;
    }

    fprintf(dot_file, "%s", dot_content);
    free(dot_content);

    // Move file pointer to beginning of file
    rewind(dot_file);

    // Get the file descriptor for the tmpfile
    int fd = fileno(dot_file);

    // Convert DOT to PNG using a pipe to avoid writing to a physical file
    int pipe_fd[2];
    if (pipe(pipe_fd) < 0) {
        fclose(dot_file);
        return;
    }

    pid_t dot_pid = fork();
    if (dot_pid < 0) {
        close(pipe_fd[0]);
        close(pipe_fd[1]);
        fclose(dot_file);
        return;
    } else if (dot_pid == 0) {
        // Child process for dot
        close(pipe_fd[0]);

        dup2(fd, 0);  // Redirect stdin to tmpfile
        dup2(pipe_fd[1], 1);  // Redirect stdout to pipe

        close(fd);
        close(pipe_fd[1]);

        execlp("dot", "dot", "-Tpng", NULL);
        _exit(EXIT_FAILURE);
    }

    close(fd);
    close(pipe_fd[1]);

    // Read output from dot command
    int status;
    waitpid(dot_pid, &status, 0);

    // Now attempt to write PNG output to a temporary file
    char png_path[] = "/tmp/filter_graph_XXXXXX.png";
    int png_fd = mkstemp(png_path);
    if (png_fd < 0) {
        close(pipe_fd[0]);
        fclose(dot_file);
        return;
    }

    close(pipe_fd[0]);

    // Open the PNG with gnome-open
    pid_t open_pid = fork();
    if (open_pid < 0) {
        close(png_fd);
        return;
    } else if (open_pid == 0) {
        execlp("gnome-open", "gnome-open", png_path, NULL);
        _exit(EXIT_FAILURE);
    }

    close(png_fd);
    fclose(dot_file);
}

#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

// Assume RSFilter is defined elsewhere in the project
typedef struct RSFilter RSFilter;

// Assume generate_dot_representation is a defined helper function elsewhere in the project
char* generate_dot_representation(RSFilter *filter);

void visualize_filter_graph(RSFilter *filter) {
    if (!filter) {
        fprintf(stderr, "Warning: Invalid filter provided.\n");
        return;
    }

    char *dotContent = generate_dot_representation(filter);
    if (!dotContent) {
        fprintf(stderr, "Warning: Failed to generate DOT content.\n");
        return;
    }

    FILE *dotFile = tmpfile();
    if (!dotFile) {
        fprintf(stderr, "Warning: Failed to create temporary file.\n");
        free(dotContent);
        return;
    }

    if (fprintf(dotFile, "%s", dotContent) < 0) {
        fprintf(stderr, "Warning: Failed to write DOT content to file.\n");
        free(dotContent);
        fclose(dotFile);
        return;
    }

    rewind(dotFile);

    char dotFilePath[] = "/tmp/filter_graphXXXXXX";
    int fd = mkstemp(dotFilePath);
    if (fd == -1) {
        fprintf(stderr, "Warning: Failed to create temporary file.\n");
        free(dotContent);
        fclose(dotFile);
        return;
    }

    // Write the content to the new file
    char *buffer = malloc(4096);
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, 4096, dotFile)) > 0) {
        write(fd, buffer, bytesRead);
    }
    free(buffer);
    fclose(dotFile);
    close(fd);

    char pngFilePath[strlen(dotFilePath) + 5];
    snprintf(pngFilePath, sizeof(pngFilePath), "%s.png", dotFilePath);

    // Convert DOT file to PNG using dot
    char command[1024];
    snprintf(command, sizeof(command), "dot -Tpng %s -o %s", dotFilePath, pngFilePath);
    int dotStatus = system(command);
    if (dotStatus == -1 || WIFSIGNALED(dotStatus) || WEXITSTATUS(dotStatus) != 0) {
        fprintf(stderr, "Warning: Failed to convert DOT to PNG.\n");
        unlink(dotFilePath);
        free(dotContent);
        return;
    }

    // Open the generated PNG using gnome-open
    snprintf(command, sizeof(command), "gnome-open %s", pngFilePath);
    int openStatus = system(command);
    if (openStatus == -1 || WIFSIGNALED(openStatus) || WEXITSTATUS(openStatus) != 0) {
        fprintf(stderr, "Warning: Failed to open generated PNG.\n");
    }

    // Clean up
    free(dotContent);
    unlink(dotFilePath);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

void visualize_filter(RSFilter *filter) {
    if (!filter) {
        fprintf(stderr, "Warning: Invalid filter provided.\n");
        return;
    }

    char *dot_content = generate_filter_dot(filter);
    if (!dot_content) {
        fprintf(stderr, "Warning: Failed to generate DOT content.\n");
        return;
    }

    char temp_filename[] = "/tmp/filter_graph_XXXXXX";
    int fd = mkstemp(temp_filename);
    if (fd == -1) {
        free(dot_content);
        fprintf(stderr, "Warning: Failed to create temporary file.\n");
        return;
    }

    FILE *temp_file = fdopen(fd, "w");
    if (!temp_file) {
        close(fd);
        free(dot_content);
        fprintf(stderr, "Warning: Failed to open temporary file.\n");
        return;
    }

    if (fprintf(temp_file, "%s", dot_content) < 0) {
        fclose(temp_file);
        free(dot_content);
        fprintf(stderr, "Warning: Failed to write DOT content to file.\n");
        return;
    }

    fclose(temp_file);
    free(dot_content);

    char png_filename[256];
    snprintf(png_filename, sizeof(png_filename), "%s.png", temp_filename);

    char *dot_cmd[] = {"dot", "-Tpng", "-o", png_filename, temp_filename, NULL};
    pid_t dot_pid = fork();

    if (dot_pid == 0) {
        execvp("dot", dot_cmd);
        _exit(EXIT_FAILURE);
    } else if (dot_pid < 0) {
        fprintf(stderr, "Warning: Failed to execute 'dot' command.\n");
        unlink(temp_filename);
        return;
    } else {
        int status;
        waitpid(dot_pid, &status, 0);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            fprintf(stderr, "Warning: 'dot' command failed to generate PNG.\n");
            unlink(temp_filename);
            unlink(png_filename);
            return;
        }
    }

    char *open_cmd[] = {"gnome-open", png_filename, NULL};
    pid_t open_pid = fork();

    if (open_pid == 0) {
        execvp("gnome-open", open_cmd);
        _exit(EXIT_FAILURE);
    } else if (open_pid < 0) {
        fprintf(stderr, "Warning: Failed to execute 'gnome-open' command.\n");
    } else {
        waitpid(open_pid, NULL, 0);
    }

    unlink(temp_filename);
}
